<script>
(function(){
 const menuBtn=document.getElementById('menuBtn');
 const navlinks=document.getElementById('navlinks');
 menuBtn.addEventListener('click',function(){const open=navlinks.classList.toggle('open');menuBtn.setAttribute('aria-expanded',String(open));menuBtn.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');menuBtn.textContent=open?'✕':'☰';});
 navlinks.querySelectorAll('a').forEach(function(link){link.addEventListener('click',function(){navlinks.classList.remove('open');menuBtn.setAttribute('aria-expanded','false');menuBtn.setAttribute('aria-label','Ouvrir le menu');menuBtn.textContent='☰';});});
 document.getElementById('year').textContent=new Date().getFullYear();
 const cards=Array.from(document.querySelectorAll('.content-card'));
 const filters=Array.from(document.querySelectorAll('.filter'));
 const search=document.getElementById('contentSearch');
 const noResults=document.getElementById('noResults');
 let activeFilter='tout';
 function applyFilter(){
  const query=search.value.trim().toLocaleLowerCase('fr');
  let visible=0;
  cards.forEach(function(card){
   const matchesType=activeFilter==='tout'||card.dataset.type===activeFilter||(activeFilter==='emotion'&&card.dataset.tags.includes('émotion'));
   const matchesQuery=!query||(card.innerText+' '+card.dataset.tags).toLocaleLowerCase('fr').includes(query);
   const show=matchesType&&matchesQuery;
   card.hidden=!show;
   if(show)visible++;
  });
  noResults.style.display=visible?'none':'block';
 }
 filters.forEach(function(button){button.addEventListener('click',function(){activeFilter=button.dataset.filter;filters.forEach(function(b){b.setAttribute('aria-pressed',String(b===button));});applyFilter();});});
 search.addEventListener('input',applyFilter);
 document.querySelectorAll('[data-filter-link]').forEach(function(link){link.addEventListener('click',function(){const requested=link.dataset.filterLink;activeFilter=requested;filters.forEach(function(b){b.setAttribute('aria-pressed',String(b.dataset.filter===requested));});applyFilter();});});
 if('IntersectionObserver' in window && !window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);}});},{threshold:.12});document.querySelectorAll('.reveal').forEach(function(el){observer.observe(el);});}else{document.querySelectorAll('.reveal').forEach(function(el){el.classList.add('visible');});}
})();
</script>
